import {loadConvertedCardPack,convertedArtInputs} from './converted-card-data.mjs';
import {toLua} from '../build-lua-data.mjs';
import {createHash} from 'node:crypto';
// Register empty holders, not thousands of static children per card/template.
import {readFileSync,existsSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';
import {buildReadyCardRegistry} from './ready-card-registry.mjs';
import {bindNativeArtPresentation} from '../card-art-samples.mjs';
import {loadPerformancePack,performanceInputs} from './performance-pack.mjs';
export const readyArtImageTemplate='AbyssReadyCardImage';
export const readyArtGroupTemplate='AbyssReadyCardGroup';
export function readyArtTemplates(){return [
 {name:readyArtImageTemplate,kind:'image',size:[1,1],image:100001,colour:'#FFFFFF',visible:false},
 {name:readyArtGroupTemplate,kind:'container',size:[144,64],visible:false,children:[]},
];}
function holder(children) {
 if(children.some(c=>c.name==='artSamples'))throw Error('Cannot combine static and dynamic card art pools');
 const plate=children.find(c=>c.name==='artPlate');
 if(JSON.stringify(plate.size)!=='[144,64]'||JSON.stringify(plate.position)!=='[0,40]')throw Error('Card aperture changed');
 const index=children.findLastIndex(c=>c.name==='art'||c.name.startsWith('art_'))+1;
 if(index===0)throw Error('Missing fallback card image');
 children.splice(index,0,{name:'artSamples',kind:'container',position:[0,40],size:[144,64],visible:false,children:[]});
}
export function attachReadyCardHosts(tree) {
 const hosts=[];
 function visit(node,path) {
  const current=[...path,node.name??''],children=node.children??node.controls??[];
  if(children.some(c=>c.name==='artPlate')){holder(children);hosts.push(current.join('/'));}
  for(const child of children)if(child.name!=='artSamples')visit(child,current);
 }
 visit(tree,[]);return hosts;
}
export function bindReadyCardPresentation(cards,{root=process.cwd()}={}) {
 const registry=buildReadyCardRegistry({root});
 bindNativeArtPresentation(cards,{registry,capacity:2657});
 for(const id of Object.keys(registry.assets))cards[id].nativeArt.runtime=true;
 return registry;
}
export const readyArtModule='abyss_ready_card_binding.lua';
export const readyArtInputs=['armaments','cleave','heavy_blade'].flatMap(id=>['asset.json','native-art.lua','native-art.json'].map(file=>`art/cards/traveler-geo/${id}/${file}`));
export function writeReadyArtBinding(directory,{imageTemplateIndex=0,containerTemplateIndex=0,enabled=false}={}) {
 for(const index of [imageTemplateIndex,containerTemplateIndex])if(!Number.isSafeInteger(index)||index<0)throw Error('Invalid card art template index');
 writeFileSync(join(directory,readyArtModule),`-- Candidate-local native template binding; zero is an offline unbound preview.\nreturn {imageTemplateIndex=${imageTemplateIndex},containerTemplateIndex=${containerTemplateIndex},enabled=${enabled?'true':'false'}}\n`);
}
export function bindReadyArtTemplates(directory,{image,group},{enabled=true}={}) {
 for(const result of [image,group])if(!Number.isSafeInteger(result?.templateIndex)||result.templateIndex<=0)throw Error('Missing actual card art template index');
 if(image.templateIndex===group.templateIndex)throw Error('Card image and group template indices must differ');
 writeReadyArtBinding(directory,{imageTemplateIndex:image.templateIndex,containerTemplateIndex:group.templateIndex,enabled});
}
export function readyArtRuntimeInventory(directory){
 if(directory&&(!existsSync(join(directory,readyArtAssetModule+'.lua'))||!readFileSync(join(directory,readyArtAssetModule+'.lua'),'utf8').includes('["runtime"]=true')))return undefined;
 if(directory&&existsSync(join(directory,'art-performance.json'))){
  const pack=JSON.parse(readFileSync(join(directory,'art-performance.json'),'utf8'));
  const rows=Object.values(pack.assets).filter(a=>typeof a.rectangles==='string');
  const max=Math.max(...rows.map(a=>a.count));
  return {renderProfile:'compact-v1',assetCount:75,preciseAssets:0,compactAssets:75,maxLivePools:10,maxShapesPerPool:max,
   maxGroupsPerPool:Math.ceil(max/60),peakDynamicControls:10*(max+Math.ceil(max/60)+1),maxCreatesPerUpdate:64,
   measurement:'offline-allocation-bound-not-official-load',officialImport:'not_run',devices:'not_run'};
 }
 return {
 assetCount:75,preciseAssets:3,compactAssets:72,maxLivePools:10,maxShapesPerPool:2657,maxGroupsPerPool:45,
 peakDynamicControls:27020,maxCreatesPerUpdate:64,measurement:'offline-allocation-bound-not-official-load',
 officialImport:'not_run',devices:'not_run',
};}

export const readyArtAssetModule='abyss_ready_card_assets';
export function readyArtSourceInputs(root=process.cwd()){return [...readyArtInputs,...convertedArtInputs(root),...performanceInputs(root)];}
export function prepareReadyCardAssets({root=process.cwd(),compact=false}={}) {
 const cards={armaments:{},cleave:{},heavy_blade:{}};
 bindReadyCardPresentation(cards,{root});
 const assets=Object.fromEntries(Object.entries(cards).map(([id,row])=>[id,row.nativeArt]));
 const pack=loadConvertedCardPack(root);
 for(const [id,row]of Object.entries(pack.cards))assets[id]={cardId:id,runtime:true,rectangles:row.rectangles,
  rectangleCount:row.rectangleCount,rectangleEncoding:pack.encoding,sourcePreviewSha256:row.sourcePreviewSha256,
  rectangleSha256:createHash('sha256').update(row.rectangles).digest('hex')};
 if(compact)for(const [id,a]of Object.entries(loadPerformancePack(root).assets))if(assets[id])assets[id]={cardId:id,runtime:true,renderProfile:'compact-v1',rectangles:a.rectangles,
  rectangleCount:a.count,rectangleEncoding:'xywh-rgb24-hex14',sourcePreviewSha256:a.sha256,
  rectangleSha256:createHash('sha256').update(a.rectangles).digest('hex')};
 return assets;
}
export function writeReadyCardAssets(directory,{root=process.cwd(),prepared}={}) {
 const assets=prepared??prepareReadyCardAssets({root});
 writeFileSync(join(directory,readyArtAssetModule+'.lua'),'-- Frozen reviewed artwork, loaded only after native template binding.\nreturn '+toLua(assets)+'\n');
 return assets;
}

import {monsterPowerTemplateName,monsterActorBindingModule,monsterActorTemplateName} from './monster-art.mjs';
import {normalizeArtFeatures,artFeatureBuildArgs,artBuildOptionsFromReceipt} from './art-features.mjs';
import {portraitRuntimeInputs,portraitModule} from './official-portraits.mjs';
import {lightweightInputs} from './lightweight-2d-profile.mjs';
import {uiProfileFromReceipt} from './ui-profile.mjs';
import {prepareAuditV25CardInputs} from './v25-card-audit-inputs.mjs';
import {prepareAuditV25UiMasks} from './v25-ui-mask-audit-inputs.mjs';
import {loadNativeUiEncoder} from './native-ui-encoder.mjs';
import {embeddedScripts} from './native-script-inventory.mjs';
import {readyArtImageTemplate,readyArtGroupTemplate} from './art/ready-card-runtime.mjs';
import {selectionHalfTemplate} from './lumine-selection-background.mjs';
import {backgroundInputs, backgroundModule, backgroundTemplate} from './official-background.mjs';
// Local offline tools only. Never calls a save mutation, import or playtest API.
import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { resolve, join, dirname, isAbsolute } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { compareNativeCandidate, requireSourceSha, sha256, candidateEntrySource } from './native-candidate-audit.mjs';
import { exportedCandidatePath, newEvidenceDirectory } from './native-audit-paths.mjs';
import { releaseSourceFiles } from './release-notes.mjs';

export function auditPortraitTemplateBindings(receipt,templates,{sourceSha,candidateHash,officialAssets=false,selectionAvatar=false}={}){
  const single=name=>{const rows=templates.filter(row=>row?.template?.name===name);return rows.length===1?rows[0]:undefined;};
  const image=single(readyArtImageTemplate),container=single(readyArtGroupTemplate);
  if(receipt?.sourceCommit!==sourceSha||receipt?.candidate?.sha256!==candidateHash
    ||!Number.isSafeInteger(image?.templateIndex)||image.templateIndex<=0
    ||!Number.isSafeInteger(container?.templateIndex)||container.templateIndex<=0||image.templateIndex===container.templateIndex
    ||receipt?.officialPortraits?.imageTemplateIndex!==image.templateIndex
    ||receipt?.officialPortraits?.containerTemplateIndex!==container.templateIndex)
    throw Error('Portrait runtime requires matching same-candidate template binding');
  const half=officialAssets&&selectionAvatar?single(selectionHalfTemplate):undefined;
  if(officialAssets&&selectionAvatar&&(!Number.isSafeInteger(half?.templateIndex)||half.templateIndex<=0
    ||half.templateIndex!==receipt?.officialPortraits?.selectionHalfImageTemplateIndex
    ||templates.filter(row=>row?.templateIndex===half.templateIndex).length!==1))
    throw Error('Official selection requires matching unique same-candidate half-triangle template binding');
  return {image,container,...(half?{half}:{})};
}

export function auditUiBuildArgs(receipt,{registryPath,deferExperimentalInventory=false,v25CardAssetsPath,v25UiMasksPath}={}) {
  const options=receipt===undefined?{artFeatures:normalizeArtFeatures()}:artBuildOptionsFromReceipt(receipt,{deferExperimentalInventory});
  return ['scripts/build-ui.mjs',...artFeatureBuildArgs(options.artFeatures),...(options.officialAssets?['--official-assets']:[]),...(options.v25UiMasks?[`--v25-ui-masks=${v25UiMasksPath??options.v25UiMasks}`]:[]),...(options.v25CardAssets?[`--v25-card-assets=${v25CardAssetsPath??options.v25CardAssets}`]:[]),...(options.v25BattleChrome?['--v25-battle-chrome']:[]),...(uiProfileFromReceipt(receipt)?['--native-page-lifecycle']:[]),...(options.lightweight2d?['--lightweight-2d']:[]),...(options.legacyCardFrames?['--legacy-card-frames']:[]),...(options.nativeCardArt?
    [`--native-card-art-registry=${registryPath??options.nativeCardArt.registry}`,...options.nativeCardArt.hosts.map(host=>`--native-card-art-host=${host}`)]:[])];
}

// Choose only from pinned Git paths, never read the current checkout's artwork.
export function auditAssetInputs(receipt,{deferExperimentalInventory=false}={}) {
  const options=receipt===undefined?{artFeatures:normalizeArtFeatures()}:artBuildOptionsFromReceipt(receipt,{deferExperimentalInventory});
  const flags=options.artFeatures,portable=new Map();
  const safePath=value=>typeof value==='string'&&value&&!value.startsWith('-')&&!value.startsWith(':')&&!value.includes('\0')&&!isAbsolute(value)&&!value.split(/[\\/]/).includes('..')&&!/^[A-Za-z]:/.test(value);
  for(const record of receipt?.nativeCardArt?.inputs??[]){
    const original=record.path?.replaceAll('\\','/');
    const matches=(receipt.inputs??[]).filter(row=>safePath(row.path)&&row.sha256===record.sha256&&row.bytes===record.bytes
      &&(original===row.path||original?.endsWith('/'+row.path)));
    if(matches.length!==1)throw Error('Static artwork lacks unambiguous portable source provenance');
    portable.set(record.path,matches[0].path);
  }
  const registryPath=options.nativeCardArt?portable.get(receipt.nativeCardArt.registry.path):undefined;
  if(options.nativeCardArt&&!registryPath)throw Error('Static registry lacks portable source provenance');
  return {paths:[...(flags.monsters?receipt.nativeMonsterArt.inputs.map(row=>row.path):[]),...(flags.menuBackground?backgroundInputs:[]),...(flags.cards&&!options.nativeCardArt?['art/cards/traveler-geo']:[]),
    ...portraitRuntimeInputs(flags),...(options.lightweight2d?lightweightInputs:[]),...portable.values()],registryPath,portable};
}
export function prepareAuditStaticRegistry(snapshot,receipt,selection) {
  if(!selection.registryPath)return;
  for(const record of receipt.nativeCardArt.inputs){
    const bytes=readFileSync(join(snapshot,selection.portable.get(record.path)));
    if(bytes.length!==record.bytes||sha256(bytes)!==record.sha256)throw Error('Pinned static artwork differs from receipt source provenance');
  }
  const path=join(snapshot,selection.registryPath),registry=JSON.parse(readFileSync(path,'utf8'));
  if(!Array.isArray(registry.sourceInputs))throw Error('Static registry lacks source inputs');
  for(const input of registry.sourceInputs){
    const fingerprints=receipt.nativeCardArt.inputs.filter(record=>record.sha256===input.sha256);
    const locators=fingerprints.filter(record=>record.path.replaceAll('\\','/')===input.path?.replaceAll('\\','/')||selection.portable.get(record.path)===input.path);
    const matches=locators.length?locators:fingerprints;
    if(matches.length!==1)throw Error('Static registry source cannot be rebased to pinned snapshot');
    input.path=selection.portable.get(matches[0].path);
  }
  // Only filesystem locators change; all original registry/source bytes were checked above.
  writeFileSync(path,JSON.stringify(registry));
}

const usage = 'node scripts/audit-native-candidate.mjs --source <full-commit-SHA> --candidate <full-game.gil> --output <new-directory> [--receipt <candidate.json>] [--bgm]';
function argumentsOf(args) {
  const options = {};
  for (let i = 0; i < args.length; i++) {
    const flag = args[i];
    if (flag === '--bgm') options.bgm = true;
    else if (['--source', '--candidate', '--output', '--receipt'].includes(flag) && args[i + 1] && !args[i + 1].startsWith('--')) options[flag.slice(2)] = args[++i];
    else throw new Error(`Invalid argument ${flag}. Usage: ${usage}`);
  }
  requireSourceSha(options.source);
  if (!options.candidate || !options.output) throw new Error(`Usage: ${usage}`);
  return options;
}

export async function auditNativeCandidate(options) {
  const sourceSha = requireSourceSha(options.source);
  const mapPath = exportedCandidatePath(options.candidate);
  const output = newEvidenceDirectory(options.output);
  if (existsSync(output)) throw new Error('Output must be a new directory; existing evidence is preserved');
  const before = sha256(readFileSync(mapPath));
  const buildReceipt = options.receipt === undefined ? undefined : JSON.parse(readFileSync(options.receipt, 'utf8'));
  mkdirSync(output, { recursive: true });
  const repo = resolve(dirname(fileURLToPath(import.meta.url)), '..');
  const save = (name, value) => { writeFileSync(join(output, name), JSON.stringify(value, null, 2) + '\n'); return value; };
  function run(command, args, settings = {}) {
    const result = spawnSync(command, args, { cwd: repo, maxBuffer: 50 * 1024 * 1024, ...settings });
    if (result.status !== 0) throw new Error(`${command}: ${result.error?.message || result.stderr?.toString()}`);
    return result.stdout;
  }
  let report;
  try {
    const artOptions=buildReceipt===undefined?{artFeatures:normalizeArtFeatures()}:artBuildOptionsFromReceipt(buildReceipt,{deferExperimentalInventory:true});
    const flags=artOptions.artFeatures,dynamicCards=flags.cards&&!artOptions.nativeCardArt,portraits=flags.selectionAvatar||flags.battlePortrait;
    if(buildReceipt&&(buildReceipt.sourceCommit!==sourceSha||buildReceipt.candidate?.sha256!==before))throw Error('Art features require matching same-candidate receipt');
    const resolved = run('git', ['rev-parse', `${sourceSha}^{commit}`], { encoding: 'utf8' }).trim();
    if (resolved !== sourceSha) throw new Error('Source SHA did not resolve to that exact commit');
    const toolRoot = process.env.MILIASTRA_MCP_ROOT || 'D:/MiliastraTools/genshin-miliastra-mcp';
    const load = path => import(pathToFileURL(join(toolRoot, path)));
    const { Client } = await load('node_modules/@modelcontextprotocol/sdk/dist/esm/client/index.js');
    const { StdioClientTransport } = await load('node_modules/@modelcontextprotocol/sdk/dist/esm/client/stdio.js');
    const client = new Client({ name: 'abyss-candidate-readback', version: '1' });
    await client.connect(new StdioClientTransport({ command: process.execPath, args: [join(toolRoot, 'src/server.mjs')],
      env: { ...process.env, MILIASTRA_WORKSPACE: output, MILIASTRA_ALLOW_LIVE_WRITE: '0' } }));
    try {
      for (const uri of ['miliastra://workflow', 'miliastra://platform-rules']) save(`${uri.split('//')[1]}.json`, await client.readResource({ uri }));
    } finally { await client.close(); }
    const {native,identity}=await loadNativeUiEncoder(toolRoot);
    if(buildReceipt?.toolchainIdentity)for(const key of ['adapter','sourceSha256','sourceBytes','helperSha256','helperBytes','anchorCount']){
      if(buildReceipt.toolchainIdentity[key]!==identity[key])throw Error('Native UI encoder identity differs: '+key);
    }
    save('native-ui-encoder.json',identity);
    const { getClientUi, checkClientScripts } = native;
    const { inspectFile } = await load('src/adapter.mjs');
    const { container, fields, one } = await load('src/scene/wire.mjs');
    const scripts = save('scripts.json', embeddedScripts({ mapPath, includeSource: true },{container,fields,one}));
    const ui = save('ui.json', getClientUi({ mapPath, ui: 'SlayTheAbyss' }));
    const template = save('template.json', getClientUi({ mapPath, template: 'AbyssDeckCard' }));
    const background = flags.menuBackground
      ? save('background-template.json', getClientUi({mapPath,template:backgroundTemplate})) : undefined;
    const runtimeNames=[...(flags.cards||portraits||flags.menuBackground||buildReceipt?.v25CardAssets||buildReceipt?.v25UiMasks?[readyArtImageTemplate]:[]),readyArtGroupTemplate,monsterActorTemplateName,monsterPowerTemplateName,
      ...(artOptions.officialAssets&&flags.selectionAvatar?[selectionHalfTemplate]:[]),...Object.keys(buildReceipt?.v25CardAssets?.templateIndices??{}),...Object.keys(buildReceipt?.v25UiMasks?.templateIndices??{})];
    const runtimeTemplates=runtimeNames.map(name=>save(name+'.json',getClientUi({mapPath,template:name})));
    const inspected = save('inspect.json', inspectFile(mapPath));
    const checked = save('static-check.json', checkClientScripts({ mapPath }));
    const uiRecord = fields(one(container(readFileSync(mapPath)), 50)).find(field => field.id === 1
      && field.wire === 2 && one(field.data, 2).toString('utf8') === 'abyss_ui');
    const records = fields(uiRecord.data).filter(field => [7, 8].includes(field.id) && field.wire === 2
      && one(field.data, 2).toString('utf8') === 'nativeBgmEnabled').map(field => ({ section: field.id,
      name: 'nativeBgmEnabled', type: Number(one(field.data, 3, 0)), code: Number(one(field.data, 10, 0)),
      value: fields(one(one(field.data, 4), 106)).some(value => value.id === 1 && value.value === 1n), encodedHex: field.raw.toString('hex') }));
    const parameters = save('parameters.json', { script: 'abyss_ui', records });
    const snapshot = join(output, 'source'); mkdirSync(snapshot);
    const selection=auditAssetInputs(buildReceipt,{deferExperimentalInventory:true}),assetInputs=selection.paths,registryPath=selection.registryPath;
    run('tar', ['-xf', '-', '-C', snapshot], { input: run('git', ['archive', sourceSha, '--',
      'src/lua', 'data', 'scripts', 'tools', ...releaseSourceFiles, ...assetInputs]) });
    prepareAuditStaticRegistry(snapshot,buildReceipt,selection);
    const v25Private=artOptions.v25CardAssets?prepareAuditV25CardInputs({snapshot,receipt:buildReceipt,root:repo}):null;
    const v25Masks=artOptions.v25UiMasks?await prepareAuditV25UiMasks({snapshot,receipt:buildReceipt,root:repo}):null;
    if(v25Masks)save('v25-ui-mask-locators.json',v25Masks.locatorRebase);
    if(v25Private)save('v25-private-locators.json',v25Private.locatorRebase);
    // Geometry identity belongs to the requested source epoch, never the tool checkout.
    if(artOptions.lightweight2d){
      const pinned=await import(pathToFileURL(join(snapshot,'scripts/art-features.mjs')));
      pinned.artBuildOptionsFromReceipt(buildReceipt);
    }
    for (const script of ['build-lua-data.mjs', 'build-ui.mjs']) writeFileSync(join(output, `${script}.log`),
      run(process.execPath, script==='build-ui.mjs'?auditUiBuildArgs(buildReceipt,{registryPath,deferExperimentalInventory:true,v25CardAssetsPath:v25Private?.v25CardAssetsPath,v25UiMasksPath:v25Masks?.v25UiMasksPath}):[`scripts/${script}`], { cwd: snapshot }));
    const { candidateScriptFiles } = await import(pathToFileURL(join(snapshot, 'scripts/native-candidate-scripts.mjs')));
    // Reproduce the actual producer's module recipe at the pinned source epoch.
    const {generatedRuntimeModules}=await import(pathToFileURL(join(snapshot,'scripts/build-native-candidate.mjs')));
    const deployment = candidateScriptFiles(join(snapshot, 'src/lua'), join(snapshot, 'build/lua'),Object.keys(generatedRuntimeModules));
    const uiBgmParameter = deployment.find(script => script.name === 'abyss_ui')?.variables?.find(variable => variable.name === 'nativeBgmEnabled');
    if(flags.menuBackground) {
      if(buildReceipt?.sourceCommit!==sourceSha || buildReceipt?.candidate?.sha256!==before
        || buildReceipt?.officialBackground?.templateIndex!==background?.templateIndex)
        throw Error('Official background requires matching same-candidate receipt and template readback');
      const {bindBackgroundTemplate}=await import(pathToFileURL(join(snapshot,'scripts/official-background.mjs')));
      bindBackgroundTemplate(join(snapshot,'build/lua'),background,{root:snapshot,containerTemplateIndex:runtimeTemplates?.[1]?.templateIndex});
    }
    const sharedReceipt=dynamicCards?buildReceipt?.readyCardArt:flags.cards||portraits?buildReceipt?.officialPortraits:buildReceipt?.officialBackground;
    if((flags.cards||portraits||flags.menuBackground)&&(runtimeTemplates[0]?.templateIndex!==sharedReceipt?.imageTemplateIndex||runtimeTemplates[1]?.templateIndex!==sharedReceipt?.containerTemplateIndex))throw Error('Artwork requires matching shared template binding');
    if(dynamicCards) {
      if(buildReceipt?.sourceCommit!==sourceSha||buildReceipt?.candidate?.sha256!==before
        ||runtimeTemplates?.[0]?.templateIndex!==buildReceipt?.readyCardArt?.imageTemplateIndex
        ||runtimeTemplates?.[1]?.templateIndex!==buildReceipt?.readyCardArt?.containerTemplateIndex)
        throw Error('Ready artwork requires matching same-candidate binding and templates');
      const {bindReadyArtTemplates}=await import(pathToFileURL(join(snapshot,'scripts/art/ready-card-runtime.mjs')));
      bindReadyArtTemplates(join(snapshot,'build/lua'),{image:runtimeTemplates[0],group:runtimeTemplates[1]},{enabled:buildReceipt.readyCardArt.enabled});
    }
    if(portraits||flags.cards||flags.menuBackground) {
      const portraitBindings=auditPortraitTemplateBindings(buildReceipt,runtimeTemplates,{sourceSha,candidateHash:before,
        officialAssets:artOptions.officialAssets,selectionAvatar:flags.selectionAvatar});
      const {bindPortraitTemplates}=await import(pathToFileURL(join(snapshot,'scripts/official-portraits.mjs')));
      bindPortraitTemplates(join(snapshot,'build/lua'),portraitBindings,{root:snapshot,...flags,v25BattleChrome:artOptions.v25BattleChrome,officialAssets:artOptions.officialAssets});
    }
    if(!deployment.some(module=>module.name===monsterActorBindingModule))throw Error('Missing monster actor runtime binding');
    {
      const power=runtimeTemplates?.find(row=>row.template?.name===monsterPowerTemplateName);
      const actor=runtimeTemplates?.find(row=>row.template?.name===monsterActorTemplateName);
      const group=runtimeTemplates?.find(row=>row.template?.name===readyArtGroupTemplate);
      if(buildReceipt?.sourceCommit!==sourceSha||buildReceipt?.candidate?.sha256!==before
        ||power?.templateIndex!==buildReceipt?.monsterActors?.powerTemplateIndex
        ||actor?.templateIndex!==buildReceipt?.monsterActors?.templateIndex
        ||group?.templateIndex!==buildReceipt?.monsterActors?.containerTemplateIndex)
        throw Error('Monster actors require matching same-candidate binding and template readback');
      const {bindMonsterActorTemplates}=await import(pathToFileURL(join(snapshot,'scripts/monster-art.mjs')));
      bindMonsterActorTemplates(join(snapshot,'build/lua'),{actor,group,power});
    }
    if(v25Private||v25Masks){
      if(buildReceipt.v25TextureRuntime){
        const runtime=buildReceipt.v25TextureRuntime;
        if(runtime.profile!=='source-rgba-packed-v1'
          ||runtime.imageTemplateIndex!==runtimeTemplates.find(row=>row.template?.name===readyArtImageTemplate)?.templateIndex
          ||runtime.containerTemplateIndex!==runtimeTemplates.find(row=>row.template?.name===readyArtGroupTemplate)?.templateIndex)
          throw Error('Packed V25 textures require same-candidate shared templates');
      }
      const {writeV25CardBinding}=await import(pathToFileURL(join(snapshot,'scripts/v25-card-binding.mjs')));
      writeV25CardBinding(join(snapshot,'build/lua'),v25Private?.prepared,buildReceipt.v25CardAssets?.templateIndices,
        {masks:v25Masks?.prepared,maskIndices:buildReceipt.v25UiMasks?.templateIndices,
          imageTemplateId:runtimeTemplates.find(row=>row.template?.name===readyArtImageTemplate)?.templateIndex,
          groupTemplateId:runtimeTemplates.find(row=>row.template?.name===readyArtGroupTemplate)?.templateIndex});
    }
    const modules = deployment.map(({ name, sourceFile }) => {
      const source = readFileSync(sourceFile, 'utf8');
      return { name, source: name === 'abyss_ui' ? candidateEntrySource(source, buildReceipt, before) : source };
    });
    const expectedUi = JSON.parse(readFileSync(join(snapshot, 'build/lua/game-ui.json'), 'utf8'));
    const expectedTemplates = JSON.parse(readFileSync(join(snapshot, 'build/lua/game-ui-templates.json'), 'utf8'));
    const expectedTemplate = expectedTemplates.find(template => template.name === 'AbyssDeckCard');
    const expectedRuntimeTemplates=runtimeNames.map(name=>({
      template:expectedTemplates.find(row=>row.name===name),templateIndex:buildReceipt?.v25CardAssets?.templateIndices[name]??buildReceipt?.v25UiMasks?.templateIndices[name]??(name===monsterPowerTemplateName?buildReceipt?.monsterActors?.powerTemplateIndex:
        name===monsterActorTemplateName?buildReceipt?.monsterActors?.templateIndex:name===selectionHalfTemplate?
        buildReceipt?.officialPortraits?.selectionHalfImageTemplateIndex:name===readyArtImageTemplate?
        buildReceipt?.v25TextureRuntime?.imageTemplateIndex??sharedReceipt?.imageTemplateIndex:
        buildReceipt?.v25TextureRuntime?.containerTemplateIndex??sharedReceipt?.containerTemplateIndex??buildReceipt?.monsterActors?.containerTemplateIndex)}));
    const expectedBackgroundTemplate = expectedTemplates.find(template => template.name === backgroundTemplate);
    const expectedBackground = expectedBackgroundTemplate ? {template:expectedBackgroundTemplate,
