import {monsterActorInventory,monsterActorTemplateName} from './monster-art.mjs';
import {artBuildOptionsFromReceipt,readArtFeatures} from './art-features.mjs';
import {portraitRuntimeInventory} from './official-portraits.mjs';
import {readyArtRuntimeInventory} from './art/ready-card-runtime.mjs';
import {backgroundRuntimeInventory} from './official-background.mjs';
import { readFileSync, mkdirSync, writeFileSync, realpathSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { candidateScriptFiles, excludedProductionModules } from './native-candidate-scripts.mjs';
import { checkArchitecture } from './check-architecture.mjs';
import { assertNativeUiCapacity } from './build-ui.mjs';
import { sourceInputs, payloadDigest } from './build-native-candidate.mjs';
import { verifyNativeCardArtReceipt } from './card-art-samples.mjs';
import { validDate } from './evidence-files.mjs';
import { gitSourceIdentity } from './release-notes.mjs';
import {assertCandidateArtReceipt} from './candidate-art-policy.mjs';

const hash = bytes => createHash('sha256').update(bytes).digest('hex');
export function packageInventory(directory = 'build/lua') {
  const artFeatures=readArtFeatures(directory);
  const architecture = checkArchitecture();
  if (architecture.errors.length) throw Error('Production dependency analysis failed; run check:architecture');
  for (const edge of architecture.edges) if (excludedProductionModules.includes(edge.to))
    throw Error(`Excluded production dependency: ${edge.from} -> ${edge.to}`);
  const modules = candidateScriptFiles('src/lua', directory).map(({name, sourceFile}) => {
    const bytes = readFileSync(sourceFile);
    return { name, bytes: bytes.length, sha256: hash(bytes) };
  });
  const reachable = new Set();
  function dependency(name) {
    if (reachable.has(name)) return;
    reachable.add(name);
    for (const edge of architecture.edges) if (edge.from === name) dependency(edge.to);
  }
  dependency('abyss_ui');
  const unreachable = modules.filter(row => !reachable.has(row.name));
  if (unreachable.length) throw Error(`Unreferenced production modules: ${unreachable.map(row => row.name).join(', ')}`);
  const digests = new Set();
  for (const module of modules) {
    if (digests.has(module.sha256)) throw Error(`Duplicate mapped Lua payload: ${module.name}`);
    digests.add(module.sha256);
  }
  const layout = JSON.parse(readFileSync(join(directory, 'game-ui.json')));
  const templates = JSON.parse(readFileSync(join(directory, 'game-ui-templates.json')));
  const templateNames = new Set(), templateDigests = new Set();
  let controls = 0, hiddenControls = 0, artPools = 0, maxChildren = 0;
  const primitives = new Map();
  function visit(nodes, hidden = false) {
    const names = new Set();
    maxChildren = Math.max(maxChildren, nodes.length);
    for (const node of nodes) {
      if (names.has(node.name)) throw Error(`Duplicate sibling control: ${node.name}`);
      names.add(node.name); controls++;
      const invisible = hidden || node.visible === false;
      if (invisible) hiddenControls++;
      if (node.name === 'artSamples') artPools++;
      if (!node.children?.length) {
        const {name, ...shape} = node;
        const key = hash(JSON.stringify(shape));
        primitives.set(key, (primitives.get(key) ?? 0) + 1);
      }
      visit(node.children ?? [], invisible);
    }
  }
  for (const tree of [layout, ...templates]) {
    assertNativeUiCapacity(tree);
    visit(tree === layout ? layout.controls : [tree]);
  }
  for (const template of templates) {
    const {name, ...body} = template, digest = hash(JSON.stringify(body));
    if (templateNames.has(name) || templateDigests.has(digest)) throw Error(`Duplicate UI template: ${name}`);
    templateNames.add(name); templateDigests.add(digest);
  }
  return {schemaVersion: 1, ...gitSourceIdentity(process.cwd()), measurement: 'offline-production-inputs-not-official-storage', modules,
    luaBytes: modules.reduce((n, row) => n + row.bytes, 0),
    layoutJsonBytes: Buffer.byteLength(JSON.stringify(layout)), templateJsonBytes: Buffer.byteLength(JSON.stringify(templates)),
    controls, hiddenControls, templates: templates.length, artPools, maxChildren,
    monsterActors: {...monsterActorInventory(templates.find(t=>t.name===monsterActorTemplateName)),
      runtimeControlsFormula: "controlsPerActor * drawableActors + controlsPerPower * (displayedPowers + liveIntentParticles) + actorPowerAndIntentPagingContainers", peakDrawableActors: null,
      peakStatus: "unverified-not-a-static-visibility-cap"},
    repeatedPrimitiveInstances: [...primitives.values()].reduce((n, count) => n + Math.max(0, count - 1), 0),
    artFeatures,
    runtimeCardArt: artFeatures.cards ? readyArtRuntimeInventory(directory) : undefined,
    runtimePortraits: portraitRuntimeInventory(directory),
    runtimeBackgrounds: [backgroundRuntimeInventory(directory)].filter(Boolean),
    excludedModules: excludedProductionModules};
}

export function growthWarnings(report, baseline) {
  return ['luaBytes', 'layoutJsonBytes', 'templateJsonBytes', 'controls', 'hiddenControls', 'artPools']
    .filter(key => report[key] > baseline[key] * 1.1)
    .map(key => `${key}: ${baseline[key]} -> ${report[key]} (over 10% growth; review assembly, not official MB)`);
}

export const loadChecks = ['staticGlobal', 'staticRegions', 'clientCompute', 'clientMemory', 'serverProcessor',
  'serverMemory', 'combatPeak', 'complexHand', 'enemyEffectsConcurrency', 'sceneTransitions', 'repeatedEntryExit',
  'officialUpload', 'launchAndOperate', 'mobilePerformance', 'mobileInteraction'];

export function verifyPlatformRelease(receipt, evidence, readArtifact, now = Date.now()) {
  const errors = [], warnings = [];
  const fail = text => errors.push(text);
  const identity = {sourceCommit: receipt.sourceCommit, buildId: receipt.buildId,
    candidateSha256: receipt.candidate?.sha256, payloadDigest: receipt.payloadDigest};
  if (receipt.sourceDirty !== false || !/^[a-f0-9]{40}$/.test(identity.sourceCommit ?? '')
    || !/^[a-f0-9-]{36}$/.test(identity.buildId ?? '')
    || !['candidateSha256', 'payloadDigest'].every(k => /^[a-f0-9]{64}$/.test(identity[k] ?? '')))
    fail('Clean candidate identity required');
  if (!/^[a-f0-9]{64}$/.test(receipt.release?.notesSha256 ?? '')) fail('Frozen RC release provenance required');
  if (!evidence) return {status: 'UNVERIFIED', identity, errors: [...errors, 'Official load evidence missing'], warnings};
  for (const [key, value] of Object.entries(identity)) if (evidence[key] !== value) fail(`Candidate mismatch: ${key}`);
  if (evidence.schemaVersion !== 1 || !evidence.clientVersion?.trim() || !evidence.reviewer?.trim()
    || evidence.uidRedacted !== true || evidence.loadTierUnchanged !== true) fail('Missing review/client/redaction/load-tier attestation');
  const started = Date.parse(receipt.startedAt);
  function time(value) {
    const parsed = Date.parse(value);
    return validDate(value) && validDate(receipt.startedAt) && Number.isFinite(started) && parsed >= started && parsed <= now
      && parsed <= Date.parse(evidence.recordedAt);
  }
  if (!time(evidence.recordedAt)) fail('Invalid evidence time');
  function artifacts(row, name, validateBytes) {
    if (!Array.isArray(row?.artifacts) || !row.artifacts.length) { fail(`${name}: raw evidence missing`); return; }
    for (const artifact of row.artifacts) {
      try {
        const bytes = readArtifact(artifact.path);
        if (!bytes.length || !/^[a-f0-9]{64}$/.test(artifact.sha256 ?? '') || hash(bytes) !== artifact.sha256)
          fail(`${name}: evidence hash mismatch`);
        else if (validateBytes) validateBytes(bytes);
      } catch (error) { fail(`${name}: unreadable or invalid evidence (${error.message})`); }
    }
  }
  for (const [name, limit] of [['levelStorage', 20], ['serverStorage', 3]]) {
    const row = evidence[name];
    if (row?.source !== 'official-editor' || row.unit !== 'MB' || row.limitMB !== limit
      || !Number.isFinite(row.valueMB) || row.valueMB < 0 || row.valueMB > limit || !time(row.measuredAt))
      fail(`${name}: official storage reading required within ${limit}MB`);
    if (name === 'levelStorage' && row?.valueMB > 16) warnings.push('Official level storage exceeds internal 16MB budget');
    artifacts(row, name);
  }
  for (const name of loadChecks) {
    const row = evidence.checks?.[name];
    if (row?.status !== 'PASS' || !time(row.measuredAt) || !row.notes?.trim()
      || !Array.isArray(row.unresolved) || row.unresolved.length) fail(`${name}: missing or unresolved official acceptance`);
    artifacts(row, name);
  }
  if (evidence.dynamicDetectionEnabled !== true || evidence.detectorOverheadAcknowledged !== true
    || evidence.rawDynamicReport?.source !== 'official-sandbox') fail('Official dynamic report/detector attestation missing');
  artifacts(evidence.rawDynamicReport, 'rawDynamicReport');
  artifacts(evidence.screenshots, 'screenshots', bytes => {
    // Decode the same bytes whose hash was checked, not a second read of the path.
    // Pillow is already required by the UI acceptance and presentation tooling.
    const decoded = spawnSync(process.env.ABYSS_PYTHON || 'python', ['-c',
      ['from PIL import Image', 'from io import BytesIO', 'import sys',
        'data=sys.stdin.buffer.read()', 'im=Image.open(BytesIO(data))',
        'if im.format not in ("PNG", "JPEG"): raise ValueError("PNG/JPEG required")',
        'im.verify()', 'im=Image.open(BytesIO(data))', 'im.load()',
        'if im.width <= 0 or im.height <= 0: raise ValueError("Empty image")'].join('\n')],
    {input: bytes, encoding: 'utf8', timeout: 10000});
    if (decoded.error || decoded.status !== 0) throw Error('PNG/JPEG decode failed');
  });
  return {status: errors.length ? 'BLOCKED' : 'PASS', identity, clientVersion: evidence.clientVersion,
    recordedAt: evidence.recordedAt, verifiedAt: new Date(now).toISOString(), errors, warnings};
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try {
    const [mode, directory = 'build/lua', evidencePath] = process.argv.slice(2);
    let report;
    if (mode === 'daily') {
      report = packageInventory(directory);
      const baseline = JSON.parse(readFileSync('config/platform-load-baseline.json'));
      const observation = baseline.officialObservation;
      if (!Number.isFinite(observation?.levelStorageMB) || observation.levelStorageMB > 20
        || observation.levelStorageMB < 0 || !Number.isFinite(observation?.serverStorageMB)
        || observation.serverStorageMB < 0 || observation.serverStorageMB > 3)
        throw Error('Recorded official storage exceeds a hard limit or is malformed');
      report.warnings = growthWarnings(report, baseline);
      if (observation.levelStorageMB > 16) report.warnings.push('Recorded official level storage exceeds 16MB internal budget; historical reading does not verify this candidate');
      report.baselineSourceCommit = baseline.sourceCommit;
      report.delta = Object.fromEntries(['luaBytes', 'layoutJsonBytes', 'templateJsonBytes', 'controls', 'hiddenControls']
        .map(key => [key, report[key] - baseline[key]]));
    } else if (mode === 'release') {
      const receipt = JSON.parse(readFileSync(directory));
      if (hash(readFileSync(receipt.candidate.path)) !== receipt.candidate.sha256) throw Error('Candidate file changed');
      verifyNativeCardArtReceipt(receipt.nativeCardArt, {root: process.cwd()});
      assertCandidateArtReceipt(receipt);
      const artOptions=artBuildOptionsFromReceipt(receipt);
      if (payloadDigest(sourceInputs(process.cwd(),artOptions)) !== receipt.payloadDigest) throw Error('Candidate payload differs from current production inputs');
      verifyNativeCardArtReceipt(receipt.nativeCardArt, {root: process.cwd()});
      const evidence = evidencePath ? JSON.parse(readFileSync(evidencePath)) : undefined;
      // Artifact paths are relative to the evidence file, never fetched from a URL.
      const {dirname, relative, isAbsolute} = await import('node:path');
      const root = evidencePath && realpathSync(dirname(resolve(evidencePath)));
      report = verifyPlatformRelease(receipt, evidence, path => {
        if (typeof path !== 'string' || isAbsolute(path)) throw Error('Relative evidence path required');
        const target = realpathSync(resolve(root, path)), rel = relative(root, target);
        if (rel.startsWith('..') || isAbsolute(rel)) throw Error('Evidence escapes directory');
        return readFileSync(target);
      });
      if (report.status !== 'PASS') process.exitCode = 1;
    } else throw Error('Usage: platform-load.mjs daily [generated-directory] | release <candidate.json> [official-evidence.json]');
    mkdirSync('build', {recursive: true});
    writeFileSync(`build/platform-load-${mode}.json`, JSON.stringify(report, null, 2) + '\n');
    console.log(JSON.stringify({...report, ...(report.modules ? {modules: report.modules.length} : {})}, null, 2));
  } catch (error) {
    // Never leave an earlier PASS on disk after a failed candidate verification.
    mkdirSync('build', {recursive: true});
    const mode = process.argv[2] === 'release' ? 'release' : 'daily';
    writeFileSync(`build/platform-load-${mode}.json`, JSON.stringify({status: 'BLOCKED',
      verifiedAt: new Date().toISOString(), errors: [error.message]}, null, 2) + '\n');
    console.error(`BLOCKED: ${error.message}`); process.exitCode = 1;
  }
}

import test,{after} from 'node:test';
import {historicalTest,historicalInputPath} from './helpers/historical-baseline-inputs.mjs';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {existsSync,mkdirSync,mkdtempSync,readFileSync,rmSync,symlinkSync,writeFileSync,realpathSync} from 'node:fs';
import {dirname,join} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {tmpdir} from 'node:os';
import {preArtFeatureSource as currentFeature,preHistoricalArtFeatureSource as currentHistory} from './helpers/art-feature-source-inverse.mjs';
import {projectArtPerfSource as currentArtPerf} from './helpers/art-perf-source-composition.mjs';
import {preReadyArtSource as currentReadyArt} from './helpers/ready-art-source-inverse.mjs';
import {prepareBattleLifeModuleRetirement as currentRetirement} from './helpers/battle-life-source-inverse.mjs';
import {sourceEpoch} from './helpers/combined-epoch/source-epoch.mjs';
import {gameUiExtractionProof} from './helpers/epochs/develop/tests/helpers/game-ui-extraction-source-inverse.mjs';
import {nativeMonsterSourceLayer} from './helpers/epochs/develop/tests/helpers/native-monster-art-source-inverse.mjs';
import {betaSources} from './helpers/beta-integration-source.mjs';
import {round3CatalogProof} from './helpers/epochs/develop/tests/helpers/round3-catalog-source-inverse.mjs';
import {preComponentUiCiSource} from './helpers/component-ui-ci-source-inverse.mjs';

// Execute the exact original 98fef helper closure on the original 98fef inputs.
// The reviewed ready-art manifest supplies 34 files; this extension adds only
// the 24 missing retirement dependencies, reusing 22 and embedding two helpers.
// Neither historical source bodies nor their frozen assertions are rewritten.
const repository=fileURLToPath(new URL('..',import.meta.url));
const originalRoot=mkdtempSync(join(tmpdir(),'art-feature-original-helpers-'));
after(()=>rmSync(originalRoot,{recursive:true,force:true}));
const digest=bytes=>createHash('sha256').update(bytes).digest('hex');
const originalManifests=[
 ['ready-art-original-helper-sources.json','077e865ca0c6624a9616149977a4cc3428b1cb1abdca33cd3ffe8748cb66bea9'],
 ['art-feature-original-helper-sources.json','2d6a8fa255c8a32fcd97a1bc9aad5e62ddf9426ff134263bf4f67773df5dc6a1'],
];
const helperFiles={};
for(const [name,expected]of originalManifests){
 const bytes=readFileSync(new URL('./fixtures/'+name,import.meta.url));
 assert.equal(digest(bytes),expected,'complete original art-feature helper manifest: '+name);
 const manifest=JSON.parse(bytes);
 assert.equal(manifest.schemaVersion,1);
 assert.equal(manifest.sourceCommit,'98fef95d047652aa6a8880241ddff28ef320a484');
 if(name.startsWith('art-feature')){
  assert.equal(manifest.extends,'tests/fixtures/ready-art-original-helper-sources.json');
  assert.equal(manifest.entry,'tests/helpers/battle-life-source-inverse.mjs');
 }
 for(const [path,binding]of Object.entries(manifest.files)){
  assert(!Object.hasOwn(helperFiles,path),'original helpers are reused, never duplicated: '+path);
  helperFiles[path]=binding;
 }
}
function originalHelperInputs(files=helperFiles,readInput=path=>readFileSync(historicalInputPath(repository,path))){
 return Object.fromEntries(Object.entries(files).map(([path,binding])=>{
  historicalInputPath(originalRoot,path);
  assert.notEqual(Object.hasOwn(binding,'source'),Object.hasOwn(binding,'copyFrom'),'one original helper source: '+path);
  let content=binding.source===undefined?readInput(binding.copyFrom):Buffer.from(binding.source);
  if(!path.endsWith('.gz'))content=Buffer.from(content.toString('utf8').replaceAll('\r\n','\n'));
  assert.equal(digest(content),binding.sha256,'original helper complete bytes: '+path);
  assert.equal(createHash('sha1').update(`blob ${content.length}\0`).update(content).digest('hex'),binding.gitBlob,'original helper Git blob: '+path);
  return [path,content];
 }));
}
for(const [path,content]of Object.entries(originalHelperInputs())){
 const target=historicalInputPath(originalRoot,path);mkdirSync(dirname(target),{recursive:true});writeFileSync(target,content);
}
const original=name=>import(pathToFileURL(join(originalRoot,'tests/helpers/'+name+'.mjs')));
const {preIntegrationSource}=await original('pr372-integration-source');
const {preRelicArtFeatureCompositionSource}=await original('relic-art-feature-composition');
const {preRelicArtCompositionSource}=await original('relic-art-composition');
const {artFeatureSourceLayer:proof,legacyArtFeatureSourceLayer,preHistoricalArtFeatureSource,artFeatureAddedPaths,preArtFeatureSource,prepareArtFeatureRetirement}=await original('art-feature-source-inverse');
const {artPerfSourceComposition,projectArtPerfSource}=await original('art-perf-source-composition');
const {readyArtSourceLayer,preReadyArtSource}=await original('ready-art-source-inverse');
const {round2UiAddedPaths}=await original('round2-ui-source-inverse');
const {preRound3CatalogSource}=await original('round3-catalog-source-inverse');
const {prepareBattleLifeModuleRetirement}=await original('battle-life-source-inverse');

const read=path=>(proof.files[path]
 ?preIntegrationSource(path,readFileSync(path,'utf8'),'feature379')
 :preRelicArtCompositionSource(path,preRelicArtFeatureCompositionSource(path,readFileSync(path,'utf8'),'artFeature'),'art')).replaceAll('\r\n','\n');
const hash=source=>source===null?null:createHash('sha256').update(source).digest('hex');
const put=(directory,path,source)=>{const target=join(directory,path);mkdirSync(dirname(target),{recursive:true});writeFileSync(target,source);};
const temporary=()=>mkdtempSync(join(tmpdir(),'abyss-art-feature-inverse-'));

historicalTest('exact feature/fallback inverse binds every current source and restores complete baseline identities',()=>{
 assert.equal(proof.baseCommit,'1bfca6261044b92f8065bb83668c358b0a2627da');
 assert.ok(artFeatureAddedPaths.length>0,'added feature owner is explicitly bound');
 for(const path of ['scripts/native-candidate-ui-cache.mjs','scripts/native-script-inventory.mjs',
  'scripts/native-script-batch.mjs','scripts/art/performance-pack.mjs',
  'art/performance/selection-budget-v1.json','art/performance/background-budget-v1.json']){
  assert.ok(artFeatureAddedPaths.includes(path),'complete merged feature owner is bound: '+path);
 }
 for(const [path,binding]of Object.entries(proof.files)){
  const current=read(path),before=preArtFeatureSource(path,current);
  assert.equal(hash(current),binding.afterSha256,'complete approved current source: '+path);
  assert.equal(hash(before),binding.beforeSha256,'complete pre-feature baseline: '+path);
  assert.equal(preArtFeatureSource(path,current.replaceAll('\n','\r\n')),before,'native CRLF: '+path);
  assert.equal(preArtFeatureSource(path,before),before,'idempotent baseline: '+path);
  assert.equal(before===null,artFeatureAddedPaths.includes(path),'only new source becomes absent: '+path);
  assert.equal(preArtFeatureSource(path,undefined),undefined);
 }
 assert.equal(preArtFeatureSource('src/lua/unregistered.lua','return {}\n'),'return {}\n');
});

historicalTest('unknown, partial, duplicate, cross-path and reordered feature sources remain exposed',()=>{
 const entries=Object.entries(proof.files);
 for(const [path,binding]of entries){
  const current=read(path);
  const mutants=[current+'\n-- future\n',current.slice(1),current+current];
  const lines=current.split('\n'),other=lines.findIndex(line=>line!==lines[0]);
  if(other>0){[lines[0],lines[other]]=[lines[other],lines[0]];mutants.push(lines.join('\n'));}
  for(const hunk of binding.hunks){
   const partial=current.split('\n');partial.splice(hunk.at,hunk.after.length,...hunk.before);
   if(hash(partial.join('\n'))!==binding.beforeSha256)mutants.push(partial.join('\n'));
  }
  const foreign=entries.find(([otherPath])=>otherPath!==path&&read(otherPath)!==current);
  if(foreign)mutants.push(read(foreign[0]));
  for(const mutant of mutants){
   assert.notEqual(hash(mutant),binding.afterSha256);
   assert.equal(preArtFeatureSource(path,mutant),mutant,'no wildcard feature projection: '+path);
   if(hash(mutant)===legacyArtFeatureSourceLayer.files[path]?.afterSha256){
    assert.equal(hash(preHistoricalArtFeatureSource(path,mutant)),legacyArtFeatureSourceLayer.files[path].beforeSha256,'exact reviewed legacy input retains its own inverse');
    continue;
   }
   assert.equal(projectArtPerfSource(path,mutant,'art'),mutant,'unknown stays visible to old art guards: '+path);
   assert.equal(projectArtPerfSource(path,mutant,'perf'),mutant,'unknown stays visible to old performance guards: '+path);
  }
 }
});

historicalTest('recognized feature hosts bind every added owner and reject missing or drifting linked sources',()=>{
 for(const [path,binding]of Object.entries(proof.files)){
  if(binding.beforeSha256===null)continue;
  for(const changed of artFeatureAddedPaths){
   assert.throws(()=>preArtFeatureSource(path,read(path),{readSource:key=>key===changed?readFileSync(key,'utf8')+'\n// drift\n':readFileSync(key,'utf8')}),/linked source drift/);
   assert.throws(()=>preArtFeatureSource(path,read(path),{readSource:key=>{if(key===changed)throw Error('missing');return readFileSync(key,'utf8');}}),/linked source missing/);
   assert.throws(()=>preArtFeatureSource(path,read(path),{readSource:key=>key===changed?null:readFileSync(key,'utf8')}),/complete (?:art-feature|beta) linked source/);
  }
 }
});

historicalTest('feature normalization precedes both frozen art/performance and ready-art source chains',()=>{
 for(const [path,binding]of Object.entries(artPerfSourceComposition.files)){
  const current=read(path),baseline=preRound3CatalogSource(path,preArtFeatureSource(path,current));
  assert.equal(hash(baseline),binding.currentSha256,'old art/performance composition bytes remain immutable: '+path);
  for(const target of ['art','perf']){
   assert.equal(hash(projectArtPerfSource(path,current,target)),binding.targets[target].sha256);
   assert.equal(projectArtPerfSource(path,current,target),projectArtPerfSource(path,baseline,target));
  }
 }
 for(const [path,binding]of Object.entries(readyArtSourceLayer.files)){
  const current=read(path);
  assert.equal(hash(projectArtPerfSource(path,current,'art')),binding.afterSha256,'old ready-art witness remains immutable: '+path);
  assert.equal(hash(preReadyArtSource(path,current)),binding.beforeSha256,'old ready-art inverse still exact: '+path);
 }
});

historicalTest('combined feature and old-module retirement validates all owners before removing any destination',()=>{
 const directory=temporary();
 const paths=[...artFeatureAddedPaths,'src/lua/abyss_card_art_runtime.lua',...round2UiAddedPaths,'src/lua/abyss_combat_catalog.lua'];
 const live=Object.fromEntries(paths.map(path=>[path,read(path)]));
 try{
  for(const path of paths)put(directory,path,live[path]);
  put(directory,'keep.txt','keep');
