  encodeField(1,0,1073741826+i),...(s.name===undefined?[]:[encodeField(2,2,Buffer.from(s.name))]),
  encodeField(3,2,Buffer.from(s.file??s.name+'.lua')),encodeField(5,2,Buffer.from(s.source??'')),
 ])))));
