 const cardText=new Map(),cardDecorationPaths=new Set(),retiredCardDecorationPaths=new Set(),cardHosts=new Set();
 for(const [path,face]of nodes)if(child(face,'roundFrame')&&child(face,'costDisc')){
  cardHosts.add(face);
